```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("pomiary.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int maxLen = 1, maxStart = 0;
    int curLen = 1, curStart = 0;
    for (int i = 1; i < (int)dane.size(); i++) {
        if (dane[i] >= dane[i - 1]) {
            curLen++;
        } else {
            if (curLen > maxLen) {
                maxLen = curLen;
                maxStart = curStart;
            }
            curLen = 1;
            curStart = i;
        }
    }
    if (curLen > maxLen) {
        maxLen = curLen;
        maxStart = curStart;
    }
    cout << "Najdluzszy ciag niemalejacy: " << maxLen << " elementow" << endl;
    cout << "Poczatek: pozycja " << maxStart + 1 << endl;
    cout << "Elementy:";
    double suma = 0;
    for (int i = maxStart; i < maxStart + maxLen; i++) {
        cout << " " << dane[i];
        suma += dane[i];
    }
    cout << endl;
    cout << fixed << setprecision(2);
    cout << "Srednia tego ciagu: " << suma / maxLen << endl;
    return 0;
}
```

Weryfikacja:
- Ciagi niemalejace: (5,8,8) dl=3, (3,6,9,15,15) dl=5, (4,7,10,10) dl=4
- Najdluzszy: (3,6,9,15,15) od poz. 4, dl. 5
- Srednia: (3+6+9+15+15)/5 = 48/5 = 9.60
